const folderId = $('KB Config').first().json.folderId;
const folderNames = {};
folderNames[folderId] = '';
return [{ json: { pendingFolders: [ { id: folderId, name: '' } ], files: [], folderNames } }];

const state = JSON.parse(JSON.stringify($json));
const batch = state.pendingFolders.splice(0, 1);
for (const f of batch) { state.folderNames[f.id] = f.name || ''; }
state.driveQuery = '(' + batch.map(f => "'" + f.id + "' in parents").join(' or ') + ') and trashed = false';
return [{ json: state }];

const state = JSON.parse(JSON.stringify($('Crawl Next Level').first().json));
const FOLDER_MIME = 'application/vnd.google-apps.folder';
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.id) continue;
  const pid = Array.isArray(j.parents) && j.parents.length ? j.parents[0] : null;
  const parentPath = (pid && state.folderNames[pid] !== undefined) ? state.folderNames[pid] : '';
  if (j.mimeType === FOLDER_MIME) {
    const path = parentPath ? parentPath + ' / ' + (j.name || '') : (j.name || '');
    state.pendingFolders.push({ id: j.id, name: path });
  } else {
    state.files.push({ fileId: j.id, fileName: j.name || '', mimeType: j.mimeType || '', modifiedTime: j.modifiedTime || '', parentFolder: parentPath });
  }
}
delete state.driveQuery;
return [{ json: state }];
